mapper.update:
UPDATE `user`
SET username     = #{username},
    password_hash = #{passwordHash},
    status       = #{status},
    update_time  = #{updateTime}
WHERE uuid = #{uuid}

mapper.select:
SELECT uuid, username, password_hash, status, create_time, update_time
FROM `user`
WHERE uuid = #{uuid}

SELECT uuid, username, password_hash, status, create_time, update_time
FROM `user`
WHERE username = #{username}
